head.script:
{
  "@context":"https://schema.org",
  "@type":"FAQPage",
  "mainEntity":[
    {
      "@type":"Question",
      "name":"What is funded trading plus designed to present?",
      "acceptedAnswer":{"@type":"Answer","text":"funded trading plus presents a structured overview of AI-powered trading assistance, automated bot workflow components, and operational tooling that supports data-driven execution."}
    },
    {
      "@type":"Question",
      "name":"How does the FAQ search work on funded trading plus?",
      "acceptedAnswer":{"@type":"Answer","text":"The funded trading plus FAQ search filters questions instantly as you type, helping visitors locate details about automation modules, controls, and account setup flow."}
    },
    {
      "@type":"Question",
      "name":"Which controls are highlighted for risk handling?",
      "acceptedAnswer":{"@type":"Answer","text":"funded trading plus highlights configurable exposure controls, order safeguards, and monitoring views that support structured risk handling when using automated trading bots."}
    }
  ]
}

